<?php require_once '../../includes/functions.php'; requireLogin(); global $pdo; $id = $_GET['id'] ?? 0; $stmt = $pdo->prepare("SELECT * FROM erp_accounts WHERE id = ?"); $stmt->execute([$id]); $account = $stmt->fetch(); if (!$account) die("Account not found"); ?>
<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><title>Edit Account - ERP</title><link rel="stylesheet" href="../../assets/css/style.css?v=<?= time() ?>"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { background: #f5f5f5; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif; } .header { background: #fff; border-bottom: 1px solid #e0e0e0; padding: 16px 24px; display: flex; justify-content: space-between; align-items: center; } .header h1 { font-size: 1.5rem; font-weight: 500; } .container { max-width: 600px; margin: 24px auto; padding: 0 24px; } .card { background: white; border-radius: 8px; border: 1px solid #e0e0e0; overflow: hidden; } .card-body { padding: 24px; } .form-group { margin-bottom: 16px; } label { display: block; margin-bottom: 8px; font-weight: 500; color: #202124; font-size: 0.875rem; } input, select, textarea { width: 100%; padding: 10px 12px; border: 1px solid #dadce0; border-radius: 4px; font-size: 0.875rem; } .btn { padding: 10px 24px; border-radius: 4px; text-decoration: none; font-size: 0.875rem; font-weight: 500; cursor: pointer; border: none; } .btn-primary { background: #1a73e8; color: white; } .btn-secondary { background: #fff; color: #202124; border: 1px solid #dadce0; } .btn-danger { background: #dc3545; color: white; float: left; } .alert { padding: 12px 16px; border-radius: 4px; margin-bottom: 20px; display: none; } .alert-success { background: #e6f4ea; color: #137333; } .alert-error { background: #fce8e6; color: #c5221f; }</style></head>
<body><div class="header"><h1>Edit Account</h1><a href="chart-of-accounts.php" class="btn btn-secondary">Cancel</a></div><div class="container"><div class="card"><div class="card-body"><?php if ($account['is_system']): ?><div class="alert alert-error" style="display: block;">This is a system account and cannot be edited or deleted.</div><?php endif; ?><div id="alertMessage" class="alert"></div><form id="editAccountForm"><input type="hidden" name="id" value="<?= $account['id'] ?>"><div class="form-group"><label>Account Code *</label><input type="text" name="code" value="<?= htmlspecialchars($account['code']) ?>" required <?= $account['is_system'] ? 'readonly' : '' ?>></div><div class="form-group"><label>Account Name *</label><input type="text" name="name" value="<?= htmlspecialchars($account['name']) ?>" required <?= $account['is_system'] ? 'readonly' : '' ?>></div><div class="form-group"><label>Account Type *</label><select name="type" required <?= $account['is_system'] ? 'disabled' : '' ?>><option value="asset" <?= $account['type'] == 'asset' ? 'selected' : '' ?>>Asset</option><option value="liability" <?= $account['type'] == 'liability' ? 'selected' : '' ?>>Liability</option><option value="equity" <?= $account['type'] == 'equity' ? 'selected' : '' ?>>Equity</option><option value="revenue" <?= $account['type'] == 'revenue' ? 'selected' : '' ?>>Revenue</option><option value="expense" <?= $account['type'] == 'expense' ? 'selected' : '' ?>>Expense</option></select></div><div class="form-group"><label>Description</label><textarea name="description" rows="3" <?= $account['is_system'] ? 'readonly' : '' ?>><?= htmlspecialchars($account['description']) ?></textarea></div><?php if (!$account['is_system']): ?><div style="margin-top: 24px; display: flex; justify-content: space-between;"><button type="button" class="btn btn-danger" onclick="deleteAccount(<?= $account['id'] ?>)">Delete Account</button><button type="submit" class="btn btn-primary">Update Account</button></div><?php endif; ?></form></div></div></div><script>document.getElementById('editAccountForm').addEventListener('submit', async function(e) { e.preventDefault(); const btn = this.querySelector('button[type="submit"]'); btn.disabled = true; btn.textContent = 'Saving...'; const alert = document.getElementById('alertMessage'); alert.style.display = 'none'; try { const formData = new FormData(this); formData.append('action', 'update'); const response = await fetch('../api/accounts.php', { method: 'POST', body: formData }); const result = await response.json(); if (result.success) { alert.className = 'alert alert-success'; alert.textContent = 'Account updated successfully!'; alert.style.display = 'block'; setTimeout(() => window.location.href = 'chart-of-accounts.php', 1500); } else { throw new Error(result.message || 'Failed to update account'); } } catch (error) { alert.className = 'alert alert-error'; alert.textContent = error.message; alert.style.display = 'block'; btn.disabled = false; btn.textContent = 'Update Account'; } }); async function deleteAccount(id) { if (!confirm('Are you sure you want to delete this account?')) return; try { const formData = new FormData(); formData.append('action', 'delete'); formData.append('id', id); const response = await fetch('../api/accounts.php', { method: 'POST', body: formData }); const result = await response.json(); if (result.success) { window.location.href = 'chart-of-accounts.php'; } else { alert('Failed to delete: ' + result.message); } } catch (error) { alert('Error: ' + error.message); } }</script></body>
</html>

